splice<-function(filename,part){
 oldpath<-file.path(OLD,filename);lines<-readLines(oldpath);old<-fread(oldpath)
 stopifnot(length(lines)==nrow(old)+1L)
 newpaths<-file.path(OUT,'decision_thresholds',ids,part)
 if(part=='gate.tsv')newpaths<-file.path(OUT,'original/decision_thresholds',ids,part)
 newlines<-lapply(newpaths,readLines)
 stopifnot(all(vapply(newlines,function(x)identical(x[1],lines[1]),TRUE)))
 writeLines(c(lines[1],lines[-1][!old$unit%in%ids],unlist(lapply(newlines,function(x)x[-1]),use.names=FALSE)),file.path(OUT,filename))
}
